  --radius: 16px;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, "DM Sans", system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.5;
}
a { color: inherit; text-decoration: none; }
.container { width: min(1120px, 92vw); margin: 0 auto; }
.site-header {
  position: sticky; top: 0; z-index: 20;
  background: rgba(255,253,250,0.95);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid #e8e2d8;
}
.nav {
  display: flex; align-items: center; justify-content: space-between;
  padding: 0.85rem 0;
}
.logo { font-family: "Trebuchet MS", "Avenir Next", sans-serif; font-weight: 800; color: var(--green); font-size: 1.15rem; }
.nav-links { display: flex; gap: 1rem; flex-wrap: wrap; }
.nav-links a { padding: 0.45rem 0.75rem; border-radius: 999px; color: var(--forest); font-weight: 600; }
.nav-links a:hover, .nav-links a.active { background: #e8f4ec; }
.btn {
  display: inline-block; border: 0; cursor: pointer;
  background: var(--green); color: #fff; padding: 0.75rem 1rem;
  border-radius: 999px; font-weight: 700;
}
.btn.secondary { background: #fff; color: var(--forest); border: 1px solid #d7dfd8; }
.hero {
  margin: 2rem 0; padding: 2.4rem;
  border-radius: calc(var(--radius) + 6px);
  background: linear-gradient(125deg, #eff9f2 0%, #fff 45%, #fef3e4 100%);
  box-shadow: var(--shadow);
  display: grid; grid-template-columns: 1.1fr 1fr; gap: 1.5rem;
}
.hero h1, h2, h3 { font-family: "Avenir Next", "Trebuchet MS", Inter, sans-serif; line-height: 1.15; margin-top: 0; }
.media-ph {
  min-height: 220px; border-radius: 18px; overflow: hidden;
  background: linear-gradient(145deg, #d8e9dd, #f5e0c8);
  position: relative;
}
.media-ph::after {
  content: "Lifestyle coffee photography";
  position: absolute; bottom: 10px; left: 10px;
  font-size: 0.75rem; color: #2f4638;
  background: rgba(255,255,255,0.7); padding: 0.25rem 0.5rem; border-radius: 999px;
}
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; margin: 1.2rem 0 2rem; }
.card {
  background: var(--card); border-radius: var(--radius); padding: 1rem;
  border: 1px solid #ece6dc; box-shadow: var(--shadow);
}
.section-title { margin: 2.2rem 0 0.8rem; font-size: 1.8rem; color: var(--forest); }
.split { display: grid; grid-template-columns: 300px 1fr; gap: 1.25rem; }
.sidebar { position: sticky; top: 86px; align-self: start; }
.sidebar h4 { margin: 0.9rem 0 0.4rem; color: var(--forest); }
.sidebar ul { list-style: none; padding: 0; margin: 0 0 1rem; }
.sidebar li { padding: 0.4rem 0; color: var(--muted); }
.tabs { display: flex; flex-wrap: wrap; gap: 0.5rem; margin-bottom: 1rem; }
.tab-btn { border: 1px solid #c8d5c9; background: #fff; color: var(--forest); border-radius: 999px; padding: 0.5rem 0.85rem; cursor: pointer; font-weight: 700; }
.tab-btn.active { background: var(--green); color: #fff; border-color: var(--green); }
.tab-panel { display: none; }
.tab-panel.active { display: block; }
.tier-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 1rem; }
.carousel { position: relative; overflow: hidden; }
.track { display: flex; transition: transform .35s ease; gap: 1rem; }
.slide {
  min-width: calc(33.333% - 0.67rem);
  background: #fff; border: 1px solid #e8e2d8; border-radius: 14px; padding: 1rem;
}
.slide .art { height: 100px; border-radius: 12px; background: linear-gradient(145deg,#d9e8de,#f8d8b8); margin-bottom: 0.7rem; }
.carousel-controls { display: flex; gap: 0.6rem; margin: 0.7rem 0 1.2rem; }
.icon-btn { border: 1px solid #cad6cc; background: #fff; width: 40px; height: 40px; border-radius: 50%; cursor: pointer; }
.search-box { display: grid; grid-template-columns: 1fr auto auto; gap: 0.6rem; }
input[type="text"] { width: 100%; padding: 0.75rem 0.9rem; border-radius: 12px; border: 1px solid #ccd8cc; }
.suggestions { margin-top: 0.5rem; border: 1px solid #e4e8e2; background:#fff; border-radius: 12px; display:none; }
.suggestions.show { display: block; }
.suggestions button { display:block; width:100%; border:0; background:transparent; text-align:left; padding:0.6rem 0.8rem; cursor:pointer; }
.toggle-pill { display:flex; background:#ebf2ec; border-radius:999px; padding:0.2rem; width:max-content; }
.toggle-pill button { border:0; background:transparent; padding:0.45rem 0.85rem; border-radius:999px; cursor:pointer; font-weight:700; color:var(--forest); }
.toggle-pill .active { background:#fff; box-shadow: 0 1px 4px rgba(0,0,0,.08); }
.map-ph { min-height: 260px; border-radius: 16px; background: linear-gradient(160deg,#e7efe8,#f0e9dc); position: relative; }
.pin { width: 18px; height: 18px; border-radius: 50%; background: var(--green); position: absolute; border: 2px solid #fff; }
.cookie {
  position: fixed; bottom: 16px; left: 16px; right: 16px;
  background: #fff; border: 1px solid #d8e0d9; border-radius: 14px;
  box-shadow: var(--shadow); padding: 0.85rem; display:flex; justify-content:space-between; gap:1rem; align-items:center; z-index:30;
}
.footer { background: #1f2a24; color: #f4f0e9; margin-top: 2.5rem; }
.footer-grid { display:grid; grid-template-columns: repeat(5,1fr); gap: 1rem; padding: 2rem 0; }
.footer h5 { margin:0 0 .55rem; }
.footer ul { list-style:none; margin:0; padding:0; }
.footer li { margin: 0.35rem 0; color:#d8ddd7; }
.acc-toggle { display:none; }
@media (max-width: 920px) {
  .hero, .split, .tier-grid, .grid-3, .footer-grid { grid-template-columns: 1fr; }
  .sidebar { position: static; }
  .slide { min-width: calc(50% - 0.5rem); }
}
@media (max-width: 640px) {
  .nav { flex-direction: column; align-items: flex-start; gap: 0.6rem; }
  .slide { min-width: 100%; }
  .search-box { grid-template-columns: 1fr; }
  .footer-grid { display:block; padding:1rem 0; }
  .footer-col { border-top:1px solid rgba(255,255,255,.16); }
  .acc-toggle { display:flex; justify-content:space-between; align-items:center; width:100%; padding:0.9rem 0; cursor:pointer; background:none; border:0; color:#fff; font-weight:700; }
  .footer-col ul { display:none; padding-bottom:0.7rem; }
  .footer-col.open ul { display:block; }
}
